  g("index", "database index", "indeks database", ["indexes", "indices", "index"], "mod-1-3", 7, "A sorted lookup structure, like a book's index, that lets the database find rows without reading the whole table.", "Struktur pencarian terurut, seperti indeks buku, yang memungkinkan database menemukan baris tanpa membaca seluruh tabel.");
