  g("elt", "ELT", "ELT", [], "mod-0-2", 5, "Extract, Load, Transform: store the raw data first, then transform it inside the warehouse.", "Extract, Load, Transform: simpan data mentah lebih dulu, lalu ubah di dalam warehouse.");
