  g("f-string", "f-string", "f-string", ["f-strings"], "mod-0-0", 1, "Text with an f before the quotes that lets you put values inside curly braces: f\"Total {total}\".", "Teks dengan huruf f sebelum tanda kutip yang memungkinkan memasukkan nilai di dalam kurung kurawal: f\"Total {total}\".");
  g("environment-variable", "environment variable", "environment variable (variabel lingkungan)", ["environment variables", "env var"], "mod-0-1", 2, "A named setting that lives outside your code, such as a password or a file location, which a program can read when it runs.", "Pengaturan bernama yang ada di luar kodemu, seperti kata sandi atau lokasi file, yang bisa dibaca program saat berjalan.");
  g("api-key", "API key", "API key (kunci API)", ["api keys", "bearer token"], "mod-0-1", 6, "A secret code that tells an API who is asking. Treat it like a password and never put it in your code.", "Kode rahasia yang memberi tahu API siapa yang meminta. Perlakukan seperti kata sandi dan jangan taruh di kodemu.");
  g("constraint", "constraint", "constraint (batasan)", ["constraints"], "mod-0-3", 9, "A rule the database enforces on a table, such as NOT NULL or UNIQUE, so bad rows are refused.", "Aturan yang ditegakkan database pada tabel, seperti NOT NULL atau UNIQUE, sehingga baris buruk ditolak.");
  g("ddl", "DDL", "DDL", ["data definition language"], "mod-0-3", 10, "The SQL commands that define the structure of tables (CREATE, ALTER, DROP), as opposed to working with the rows.", "Perintah SQL yang mendefinisikan struktur tabel (CREATE, ALTER, DROP), berbeda dari mengolah barisnya.");
  g("dml", "DML", "DML", ["data manipulation", "insert, update, delete", "insert, update dan delete"], "mod-0-3", 9, "The SQL commands that change rows: INSERT, UPDATE and DELETE.", "Perintah SQL yang mengubah baris: INSERT, UPDATE, dan DELETE.");
  g("view", "view", "view", ["views"], "mod-0-3", 10, "A saved query that behaves like a table, so you can reuse it by name.", "Query tersimpan yang berperilaku seperti tabel, sehingga bisa dipakai ulang lewat namanya.");
  g("subquery", "subquery", "subquery", ["subqueries"], "mod-0-3", 8, "A query written inside another query, used to get a value or a list for the outer one.", "Query yang ditulis di dalam query lain, dipakai untuk mendapat nilai atau daftar bagi query luar.");
  g("self-join", "self-join", "self-join", ["self join"], "mod-0-3", 7, "Joining a table to itself, for example an employee to their manager who is in the same table.", "Menggabungkan tabel dengan dirinya sendiri, misalnya karyawan dengan atasannya yang ada di tabel yang sama.");
  g("quarantine", "quarantine", "karantina", ["quarantined"], "mod-0-2", 6, "A separate place where rejected rows are kept with a reason, instead of being deleted or silently fixed.", "Tempat terpisah menyimpan baris yang ditolak beserta alasannya, bukan menghapus atau memperbaikinya diam-diam.");
  g("staging", "staging and mart", "staging dan mart", ["staging", "marts", "mart"], "mod-1-4", 6, "Staging tables hold cleaned copies of the raw data; marts are finished tables built on top of them for analysts.", "Tabel staging menyimpan salinan bersih dari data mentah; mart adalah tabel jadi di atasnya untuk analis.");
  g("inmon", "Inmon", "Inmon", [], "mod-1-4", 6, "A way of building a warehouse: a big, normalised enterprise store first, with smaller marts fed from it.", "Cara membangun warehouse: penyimpanan perusahaan besar yang ternormalisasi lebih dulu, dengan mart kecil yang disuplai darinya.");
  g("tombstone", "tombstone", "tombstone", ["tombstones"], "mod-1-7", 4, "In some databases a delete does not remove data; it writes a marker (tombstone) that is cleaned up later.", "Di beberapa database penghapusan tidak membuang data; ia menulis penanda (tombstone) yang dibersihkan kemudian.");
  g("clustering-key", "clustering key", "clustering key", ["clustering"], "mod-1-7", 4, "The column(s) by which rows are kept sorted together, so related rows are stored side by side.", "Kolom yang dipakai untuk menjaga baris tetap terurut bersama, sehingga baris terkait tersimpan berdampingan.");
  g("schema-on-read", "schema on read", "schema on read", ["schema-on-read"], "mod-1-7", 3, "The shape of the data is decided when you read it, not when it is written, so anything can be stored.", "Bentuk data ditentukan saat dibaca, bukan saat ditulis, sehingga apa pun bisa disimpan.");
  g("date-spine", "date spine", "date spine", [], "mod-1-3", 2, "A table with one row for every date in a range, used so days with no events still show up in a report.", "Tabel dengan satu baris untuk setiap tanggal dalam rentang, agar hari tanpa kejadian tetap tampil di laporan.");
  g("join-algorithms", "hash join, sort-merge join, nested loop", "hash join, sort-merge join, nested loop", ["hash join", "sort-merge join", "nested loop", "merge join"], "mod-1-3", 11, "The three ways a database physically joins two tables. The optimiser picks one by estimating the cost.", "Tiga cara database menggabungkan dua tabel secara fisik. Optimizer memilih satu dengan memperkirakan biayanya.");
  g("cbo", "cost-based optimizer", "cost-based optimizer", ["cbo", "optimiser", "optimizer"], "mod-1-3", 11, "The part of a database that estimates the cost of several ways to run a query and chooses the cheapest.", "Bagian database yang memperkirakan biaya beberapa cara menjalankan query dan memilih yang termurah.");
  g("analyze", "ANALYZE and statistics", "ANALYZE dan statistik", ["analyze", "analyze statistics"], "mod-1-3", 6, "The database keeps counts about your tables to plan queries. ANALYZE refreshes them; stale ones lead to bad plans.", "Database menyimpan hitungan tentang tabelmu untuk merencanakan query. ANALYZE menyegarkannya; yang basi menghasilkan rencana buruk.");
  g("simd", "SIMD", "SIMD", [], "mod-2-1", 1, "A CPU feature that applies one instruction to many values at once, which is why column engines are fast.", "Fitur CPU yang menerapkan satu instruksi pada banyak nilai sekaligus, itulah mengapa mesin kolom cepat.");
  g("compression", "compression (Snappy, Zstd, gzip)", "kompresi (Snappy, Zstd, gzip)", ["compression", "snappy", "zstd", "gzip", "compressed"], "mod-2-1", 1, "Making files smaller. Snappy is fast with modest savings; Zstd compresses much more; gzip is older and slower.", "Membuat file lebih kecil. Snappy cepat dengan penghematan sedang; Zstd mengompres jauh lebih banyak; gzip lebih tua dan lambat.");
  g("object-storage", "object storage", "object storage", ["s3", "object store"], "mod-2-1", 8, "Cheap, huge storage of whole files (objects) such as Amazon S3. You cannot edit part of an object; you replace it.", "Penyimpanan file utuh (objek) yang murah dan sangat besar seperti Amazon S3. Kamu tidak bisa mengedit sebagian objek; kamu menggantinya.");
  g("durability", "durability", "durabilitas", ["durable"], "mod-2-2", 3, "Once a change is confirmed it survives a crash or power loss.", "Setelah perubahan dikonfirmasi, ia bertahan dari crash atau mati listrik.");
  g("scheduler", "scheduler", "scheduler (penjadwal)", ["schedulers"], "mod-2-4", 4, "The part of a system that decides what runs and when.", "Bagian sistem yang memutuskan apa yang berjalan dan kapan.");
  g("producer-consumer", "producer and consumer", "produser dan konsumen", ["producer", "producers", "consumer", "consumers"], "mod-2-5", 3, "The producer is the team or program that creates data; the consumer is the one that reads and uses it.", "Produser adalah tim atau program yang membuat data; konsumen adalah yang membaca dan memakainya.");
  g("slot", "slot", "slot", ["slots"], "mod-2-6", 1, "A share of a warehouse's computing power that can run one piece of work at a time.", "Bagian kekuatan komputasi warehouse yang bisa menjalankan satu potong kerja sekali waktu.");
  g("external-table", "external table", "external table", ["external tables", "tabel eksternal"], "mod-2-6", 5, "A table whose data stays in files outside the warehouse, queried in place.", "Tabel yang datanya tetap di file di luar warehouse, ditanyai di tempat.");
  g("row-access-policy", "row access policy", "row access policy", ["row access policies", "column masking"], "mod-2-6", 6, "A rule that decides which rows (or which column values) each user may see.", "Aturan yang menentukan baris mana (atau nilai kolom mana) yang boleh dilihat tiap pengguna.");
  g("local-mode", "local mode", "local mode", [], "mod-3-1", 2, "Running Spark on one computer, with the driver and workers in one process, for learning and tests.", "Menjalankan Spark di satu komputer, dengan driver dan worker dalam satu proses, untuk belajar dan tes.");
  g("b-tree", "B-tree", "B-tree", ["b+tree", "b+ tree"], "mod-1-3", 7, "The sorted tree structure behind most database indexes: finding a value takes a few steps, not a full scan.", "Struktur pohon terurut di balik kebanyakan indeks database: menemukan nilai butuh beberapa langkah, bukan pemindaian penuh.");
  g("lsm", "LSM tree and SSTable", "LSM tree dan SSTable", ["sstable", "sstables", "lsm"], "mod-1-7", 4, "A storage design for heavy writes: new data is appended in memory, flushed to sorted files, and merged later.", "Rancangan penyimpanan untuk tulis berat: data baru ditambahkan di memori, dituang ke file terurut, dan digabung kemudian.");
  g("salt", "salt and hash", "salt dan hash", ["salted", "rainbow table", "sha-256", "sha256", "hash"], "mod-1-2", 10, "A hash turns text into a fixed code that cannot be reversed. A salt is an extra secret mixed in so common values cannot be guessed from a table of hashes.", "Hash mengubah teks menjadi kode tetap yang tak bisa dibalik. Salt adalah rahasia tambahan agar nilai umum tak bisa ditebak dari tabel hash.");
  g("redis", "Redis", "Redis", [], "mod-1-7", 2, "A very fast in-memory key-value store, used for sessions and caches.", "Penyimpanan key-value di memori yang sangat cepat, dipakai untuk sesi dan cache.");
  g("bucket", "bucket", "bucket", ["buckets", "s3 bucket"], "mod-2-2", 4, "A named container in cloud object storage that holds your files.", "Wadah bernama di object storage cloud yang menyimpan file-mu.");
  g("serialization", "serialization", "serialisasi", ["serialisation", "serialize", "serialise"], "mod-2-1", 7, "Turning data in memory into bytes or text (JSON, Avro, Parquet) that can be stored or sent.", "Mengubah data di memori menjadi byte atau teks (JSON, Avro, Parquet) yang bisa disimpan atau dikirim.");
  g("bi-tool", "BI tool", "alat BI", ["bi tools", "power bi", "tableau", "metabase", "looker"], "mod-1-4", 8, "Business-intelligence software (Power BI, Tableau, Metabase) that turns tables into charts and dashboards.", "Perangkat lunak business intelligence (Power BI, Tableau, Metabase) yang mengubah tabel menjadi grafik dan dasbor.");
  g("semantic-layer", "semantic layer", "semantic layer", [], "mod-1-4", 6, "One shared definition of business metrics (revenue, active customer) that every dashboard uses.", "Satu definisi bersama metrik bisnis (pendapatan, pelanggan aktif) yang dipakai semua dasbor.");
  g("unknown-member", "unknown member", "unknown member", [], "mod-1-4", 4, "A special dimension row (for example 'Unknown customer') so facts with no match are kept, not dropped.", "Baris dimensi khusus (misalnya 'Pelanggan tidak diketahui') agar fakta tanpa pasangan tetap disimpan, tidak dibuang.");
  g("natural-key", "natural key", "natural key", ["business key"], "mod-1-4", 4, "An identifier that comes from the business itself, such as an order number or email, as opposed to a made-up surrogate key.", "Pengenal yang berasal dari bisnis itu sendiri, seperti nomor pesanan atau email, berbeda dari surrogate key buatan.");
  g("cardinality", "cardinality", "kardinalitas", [], "mod-2-1", 6, "How many different values a column has: low (a few statuses) or high (millions of ids).", "Berapa banyak nilai berbeda yang dimiliki kolom: rendah (beberapa status) atau tinggi (jutaan id).");
  g("cache", "cache", "cache", ["caching", "caches"], "mod-2-1", 8, "A small, fast copy of data kept close at hand so it need not be fetched again from a slower place.", "Salinan kecil dan cepat dari data yang disimpan dekat agar tak perlu diambil lagi dari tempat yang lebih lambat.");
  g("latency", "latency and throughput", "latensi dan throughput", ["latency", "throughput"], "mod-1-2", 10, "Latency is how long one request takes; throughput is how much work gets done per second.", "Latensi adalah berapa lama satu permintaan; throughput adalah berapa banyak kerja selesai per detik.");
  g("concurrency", "concurrency and threads", "konkurensi dan thread", ["concurrent", "concurrency", "thread", "threads", "threadpoolexecutor"], "mod-1-2", 9, "Doing several things in overlapping time. Threads let a program wait for many slow calls at once.", "Mengerjakan beberapa hal dalam waktu yang tumpang tindih. Thread membuat program bisa menunggu banyak panggilan lambat sekaligus.");
  g("sftp", "SFTP", "SFTP", [], "mod-1-6", 8, "File transfer over a secure connection; many partners drop a nightly file on an SFTP server.", "Transfer file lewat koneksi aman; banyak mitra menaruh file harian di server SFTP.");
  g("edi", "EDI", "EDI", ["electronic data interchange"], "mod-1-6", 8, "An old, strict text format companies use to exchange orders and invoices.", "Format teks lama yang ketat yang dipakai perusahaan untuk bertukar pesanan dan faktur.");
  g("jdbc", "ODBC and JDBC", "ODBC dan JDBC", ["odbc", "jdbc", "driver"], "mod-1-6", 8, "Standard connectors that let a program talk to almost any database.", "Konektor standar yang memungkinkan program berbicara dengan hampir semua database.");
  g("upsert", "upsert (MERGE)", "upsert (MERGE)", ["upsert", "upserts", "merge"], "mod-2-3", 5, "Update the row if it exists, insert it if it does not: a safe way to load the same data twice.", "Perbarui baris jika ada, masukkan jika belum: cara aman memuat data yang sama dua kali.");
  g("incremental", "incremental load", "incremental load (muat bertahap)", ["incremental", "incremental loads", "inkremental"], "mod-1-6", 4, "Loading only what changed since the last run instead of everything again.", "Memuat hanya yang berubah sejak run terakhir, bukan semuanya lagi.");
  g("dlq", "dead-letter queue", "dead-letter queue (DLQ)", ["dlq", "dead letter"], "mod-2-5", 10, "A holding place for records that cannot be processed, so one bad record does not stop the whole job.", "Tempat penampungan rekaman yang tak bisa diproses, agar satu rekaman buruk tidak menghentikan seluruh job.");
  g("jitter", "jitter", "jitter", [], "mod-1-2", 6, "A small random extra delay added to retries so many clients do not retry at the same moment.", "Jeda acak kecil yang ditambahkan pada retry agar banyak klien tidak mencoba ulang pada saat yang sama.");
  g("reconciliation", "reconciliation", "rekonsiliasi", ["reconcile", "reconciles", "reconciled"], "mod-1-6", 6, "Checking that the numbers add up: rows read equal rows stored plus rows rejected.", "Memeriksa bahwa angka-angkanya cocok: baris dibaca sama dengan baris disimpan ditambah baris ditolak.");
  g("micro-partition", "micro-partition", "micro-partition", ["micro-partitions", "zone map", "zone maps"], "mod-2-6", 2, "A small block of table data with min and max values per column, so queries skip blocks they do not need.", "Blok kecil data tabel dengan nilai min dan max per kolom, agar query melewati blok yang tak dibutuhkan.");
  g("rbac", "RBAC", "RBAC", ["role-based access control", "roles"], "mod-2-6", 9, "Giving permissions to roles (analyst, engineer) and people get roles, instead of permissions one by one.", "Memberi izin kepada peran (analis, engineer) dan orang mendapat peran, bukan izin satu per satu.");
  g("zero-copy", "zero-copy clone", "zero-copy clone", ["zero-copy cloning", "clone"], "mod-2-6", 6, "A copy of a table that costs almost nothing, because it shares the original's data until something changes.", "Salinan tabel yang hampir tak berbiaya, karena berbagi data aslinya sampai ada yang berubah.");
  g("sla", "SLA and SLO", "SLA dan SLO", ["sla", "slo", "service level"], "mod-2-5", 6, "A promise about service quality, such as 'the report is ready by 07:00 on 99% of days'.", "Janji tentang kualitas layanan, misalnya 'laporan siap pukul 07.00 pada 99% hari'.");
  g("master-data", "master data", "master data", [], "mod-2-5", 8, "The core records a company agrees on (customers, products) so every system uses the same identity.", "Catatan inti yang disepakati perusahaan (pelanggan, produk) agar semua sistem memakai identitas yang sama.");
  g("metadata", "metadata", "metadata", [], "mod-2-5", 8, "Data about data: what a table means, who owns it, its columns and when it was updated.", "Data tentang data: apa arti sebuah tabel, siapa pemiliknya, kolomnya, dan kapan diperbarui.");
  g("data-catalog", "data catalog", "data catalog", ["data catalogue"], "mod-2-5", 6, "A searchable inventory of a company's datasets with owners and descriptions.", "Inventaris dataset perusahaan yang bisa dicari, lengkap dengan pemilik dan deskripsi.");
  g("medallion", "medallion (bronze, silver, gold)", "medallion (bronze, silver, gold)", ["bronze", "silver", "gold layer", "medallion"], "mod-0-2", 5, "Three layers of tables: raw (bronze), cleaned (silver) and ready for use (gold).", "Tiga lapisan tabel: mentah (bronze), bersih (silver), dan siap pakai (gold).");
  g("kubernetes", "Kubernetes", "Kubernetes", ["k8s"], "mod-3-1", 2, "A system that runs and manages many containers across many machines.", "Sistem yang menjalankan dan mengelola banyak container di banyak mesin.");
  g("jvm", "JVM", "JVM", ["java virtual machine"], "mod-3-1", 2, "The Java Virtual Machine, the engine that runs Java and Scala programs such as Spark and Kafka.", "Java Virtual Machine, mesin yang menjalankan program Java dan Scala seperti Spark dan Kafka.");
  g("partition-pruning", "partition pruning", "partition pruning", ["pruning"], "mod-2-1", 2, "Skipping whole partitions that cannot contain the answer, because the filter rules them out.", "Melewati seluruh partisi yang tak mungkin berisi jawaban, karena filter mengeliminasinya.");
  g("spill", "spill to disk", "spill ke disk", ["spill", "spills", "spilled"], "mod-1-3", 11, "When memory runs out, an engine writes intermediate data to disk. It works but is much slower.", "Saat memori habis, mesin menulis data antara ke disk. Tetap jalan tetapi jauh lebih lambat.");
  g("lambda-kappa", "Lambda and Kappa architecture", "arsitektur Lambda dan Kappa", ["lambda architecture", "kappa architecture", "kappa"], "mod-3-3", 7, "Lambda runs separate batch and speed paths; Kappa uses one streaming path for both.", "Lambda menjalankan jalur batch dan jalur cepat terpisah; Kappa memakai satu jalur streaming untuk keduanya.");
  g("micro-batch", "micro-batch", "micro-batch", ["micro-batches"], "mod-3-3", 5, "Streaming done as many tiny batches, a few seconds each (Spark Structured Streaming).", "Streaming yang dikerjakan sebagai banyak batch kecil, beberapa detik masing-masing (Spark Structured Streaming).");
  g("allowed-lateness", "allowed lateness", "allowed lateness", [], "mod-3-3", 3, "How long a stream waits for late events before closing a window.", "Berapa lama stream menunggu event terlambat sebelum menutup sebuah window.");
  g("session-window", "session window", "session window", ["session windows", "sessionization", "session"], "mod-3-3", 2, "A window that stays open while activity continues and closes after a gap of silence.", "Window yang tetap terbuka selama ada aktivitas dan menutup setelah jeda sepi.");
  g("connector", "Kafka Connect and connector", "Kafka Connect dan connector", ["kafka connect", "connector", "connectors"], "mod-3-2", 5, "Ready-made code that moves data between Kafka and another system without you writing a program.", "Kode siap pakai yang memindahkan data antara Kafka dan sistem lain tanpa kamu menulis program.");
  g("debezium", "Debezium", "Debezium", [], "mod-3-2", 5, "A tool that reads a database's change log and publishes every change to Kafka.", "Alat yang membaca log perubahan database dan menerbitkan setiap perubahan ke Kafka.");
  g("replication-slot", "replication slot", "replication slot", ["publication"], "mod-3-2", 7, "A bookmark in PostgreSQL that keeps its change log until a consumer has read it.", "Penanda di PostgreSQL yang menyimpan log perubahannya sampai konsumen membacanya.");
  g("lsn", "LSN", "LSN", ["log sequence number"], "mod-3-2", 7, "A number that marks a position in the database change log, used to tell which change is newer.", "Angka yang menandai posisi dalam log perubahan database, dipakai untuk menentukan perubahan mana yang lebih baru.");
  g("terraform-plan", "terraform plan", "terraform plan", ["plan", "provider"], "mod-3-4", 2, "A preview of what Terraform would create, change or delete, before it does anything.", "Pratinjau apa yang akan dibuat, diubah, atau dihapus Terraform, sebelum ia melakukan apa pun.");
  g("egress", "egress", "egress", ["data transfer", "network charges"], "mod-3-4", 6, "Data leaving a cloud region or provider, which is charged by the gigabyte.", "Data yang keluar dari region atau penyedia cloud, yang ditagih per gigabyte.");
  g("availability-zone", "availability zone", "availability zone", ["zone", "zones"], "mod-3-4", 6, "A separate data centre inside a cloud region. Spreading across zones survives a failure but costs network traffic.", "Pusat data terpisah di dalam sebuah region cloud. Menyebar di beberapa zona tahan terhadap kegagalan tetapi memakan lalu lintas jaringan.");
  g("llm", "LLM", "LLM", ["large language model", "language model"], "mod-3-5", 1, "A large language model: a program trained on huge amounts of text that writes answers in natural language.", "Large language model: program yang dilatih dengan teks sangat banyak yang menulis jawaban dalam bahasa alami.");
  g("recall", "recall", "recall", [], "mod-3-5", 4, "For search: of all the truly relevant items, the share that your search actually found.", "Untuk pencarian: dari semua item yang benar-benar relevan, porsi yang berhasil ditemukan pencarianmu.");
  g("training-serving-skew", "training-serving skew", "training-serving skew", [], "mod-3-5", 7, "A model sees different feature values in production than it saw in training, so it performs worse.", "Model melihat nilai fitur yang berbeda di produksi dibanding saat pelatihan, sehingga kinerjanya lebih buruk.");
  g("label", "label", "label (target)", ["labels"], "mod-3-5", 7, "The correct answer a model learns to predict, for example 'did the customer churn'.", "Jawaban benar yang dipelajari model untuk diprediksi, misalnya 'apakah pelanggan berhenti'.");

  g("class", "class and object", "class dan object", ["class", "classes", "object", "objects", "method", "methods", "self"], "mod-1-2", 2, "A class is a blueprint that bundles data and actions; an object is one thing made from it. self means 'this object'.", "Class adalah cetak biru yang menyatukan data dan tindakan; object adalah satu benda yang dibuat darinya. self berarti 'object ini'.");
  g("type-hint", "type hint", "type hint", ["type hints", "annotation", "annotations"], "mod-1-2", 2, "A label such as price: int that says what type a value should be. Python ignores it; editors and Pydantic read it.", "Label seperti price: int yang menyatakan tipe sebuah nilai. Python mengabaikannya; editor dan Pydantic membacanya.");
  g("dataclass", "dataclass", "dataclass", ["dataclasses"], "mod-1-2", 2, "A class that only holds data. @dataclass writes __init__, a readable printout and == for you.", "Class yang hanya menyimpan data. @dataclass menuliskan __init__, tampilan cetak yang terbaca, dan == untukmu.");
  g("decorator", "decorator", "decorator", ["decorators", "decorated"], "mod-1-2", 2, "A line starting with @ above a function: hand the function to another function and use what comes back instead.", "Baris berawalan @ di atas sebuah fungsi: serahkan fungsi itu ke fungsi lain dan pakai yang dikembalikan sebagai gantinya.");
  g("lambda", "lambda", "lambda", ["lambdas"], "mod-1-2", 3, "A small one-line function without a name, such as lambda x: x + 1.", "Fungsi kecil satu baris tanpa nama, seperti lambda x: x + 1.");
  g("recursion", "recursion", "rekursi", ["recursive"], "mod-1-2", 3, "A function that calls itself on a smaller piece of the problem, with a base case that tells it when to stop.", "Fungsi yang memanggil dirinya pada potongan masalah yang lebih kecil, dengan base case yang menentukan kapan berhenti.");

  // ----- Bridge words for readers with no IT background (from a second reading audit)
  g("big-o", "Big-O (O(1), O(N))", "Big-O (O(1), O(N))", ["big-o", "o(1)", "o(n)", "o(log n)", "o(log"], "mod-1-7", 4, "A way to describe how the work grows with the amount of data. O(1) means the same effort however much data there is; O(N) means the work grows in step with the data (twice the rows, twice the time).", "Cara menggambarkan seberapa besar kerja bertambah seiring jumlah data. O(1) berarti usahanya sama berapa pun datanya; O(N) berarti kerja tumbuh seiring data (baris dua kali lipat, waktu dua kali lipat).");
  g("quorum", "quorum (R + W > N)", "quorum (R + W > N)", ["quorum", "quorums", "r + w"], "mod-1-7", 4, "With N copies of the data, if every write waits for W copies and every read asks R copies, and R + W is bigger than N, a read always overlaps the latest write and sees it.", "Dengan N salinan data, jika setiap penulisan menunggu W salinan dan setiap pembacaan menanyai R salinan, dan R + W lebih besar dari N, pembacaan selalu beririsan dengan penulisan terbaru dan melihatnya.");
  g("pacelc", "PACELC", "PACELC", [], "mod-1-7", 1, "An extension of the CAP theorem: even with no network split, a distributed database still trades latency (speed) against consistency.", "Perluasan teorema CAP: bahkan tanpa jaringan terpisah, database terdistribusi tetap menukar latensi (kecepatan) dengan konsistensi.");
  g("yaml", "YAML", "YAML", ["yml", "yaml"], "mod-1-1", 6, "A plain-text settings format where indentation (spaces at the start of a line) shows what belongs inside what. One wrong space can change the meaning.", "Format pengaturan teks biasa tempat indentasi (spasi di awal baris) menunjukkan apa yang berada di dalam apa. Satu spasi yang salah bisa mengubah artinya.");
  g("localhost", "localhost and port", "localhost dan port", ["localhost", "port", "ports", "127.0.0.1"], "mod-1-6", 4, "localhost means 'this same computer'. A port is a numbered door on a computer: http://localhost:3000 means the program listening at door 3000 on your own machine.", "localhost berarti 'komputer ini sendiri'. Port adalah pintu bernomor pada komputer: http://localhost:3000 berarti program yang mendengarkan di pintu 3000 pada mesinmu sendiri.");
  g("ip-address", "IP address", "alamat IP", ["ip address", "ip addresses", "ip"], "mod-3-4", 6, "The number that identifies a computer on a network, like a street address, for example 10.0.0.5.", "Angka yang mengenali sebuah komputer di jaringan, seperti alamat jalan, misalnya 10.0.0.5.");
  g("gc", "garbage collection (GC)", "garbage collection (GC)", ["garbage collection", "gc"], "mod-3-1", 7, "The automatic clean-up in Java and similar languages that frees memory nobody uses any more. A long pause for it can make a program look frozen.", "Pembersihan otomatis di Java dan bahasa serupa yang membebaskan memori yang tak dipakai lagi. Jeda panjang untuknya bisa membuat program tampak membeku.");
  g("kms-arn", "KMS and ARN", "KMS dan ARN", ["kms", "arn", "arns"], "mod-3-4", 3, "KMS is the cloud service that keeps encryption keys. An ARN is the full unique name of any cloud resource, such as a bucket or a role.", "KMS adalah layanan cloud yang menyimpan kunci enkripsi. ARN adalah nama unik lengkap sebuah resource cloud, seperti bucket atau role.");
  g("nat-gateway", "NAT gateway", "NAT gateway", ["nat gateway", "nat"], "mod-3-4", 6, "A cloud door that lets machines in a private network reach the internet without being reachable from it. Traffic through it is charged by the gigabyte.", "Pintu cloud yang membuat mesin di jaringan privat bisa menjangkau internet tanpa bisa dijangkau darinya. Lalu lintas melaluinya ditagih per gigabyte.");
  g("rocksdb", "RocksDB", "RocksDB", [], "mod-3-3", 4, "A fast storage engine that keeps data on local disk. Streaming engines use it to hold large state without running out of memory.", "Mesin penyimpanan cepat yang menyimpan data di disk lokal. Mesin streaming memakainya untuk menampung state besar tanpa kehabisan memori.");
  g("l2-norm", "vector norm (length)", "norma vektor (panjang)", ["norm", "l2 norm", "norma"], "mod-3-5", 2, "The length of a vector: the square root of the sum of its squared numbers. Dividing by it makes every vector length 1, so only the direction matters.", "Panjang sebuah vektor: akar dari jumlah kuadrat angka-angkanya. Membaginya membuat setiap vektor berpanjang 1, sehingga hanya arah yang penting.");
  g("data-mesh", "data mesh", "data mesh", [], "mod-2-6", 7, "An organising idea: each business team owns and publishes its own data as a product, instead of one central team doing it for everyone.", "Gagasan pengorganisasian: tiap tim bisnis memiliki dan menerbitkan datanya sendiri sebagai produk, bukan satu tim pusat yang mengerjakannya untuk semua.");
  g("iam-role", "IAM role", "IAM role", ["iam role", "iam roles", "role", "roles"], "mod-3-4", 3, "A set of cloud permissions that a program or person can temporarily take on, so no one needs a permanent password.", "Sekumpulan izin cloud yang bisa dipakai sementara oleh program atau orang, sehingga tak ada yang butuh kata sandi permanen.");
  g("strangler-fig", "strangler fig", "strangler fig", ["strangler"], "mod-2-6", 7, "A way to replace an old system step by step: the new one takes over one piece at a time while the old one keeps running, until nothing is left of the old.", "Cara mengganti sistem lama selangkah demi selangkah: yang baru mengambil alih satu bagian sekali waktu sementara yang lama tetap berjalan, sampai tak ada yang tersisa dari yang lama.");
  g("reverse-etl", "reverse ETL", "reverse ETL", [], "mod-2-4", 7, "Sending cleaned warehouse data back out to the tools people work in (a CRM, an email tool), the opposite direction of normal loading.", "Mengirim data warehouse yang sudah bersih kembali ke alat tempat orang bekerja (CRM, alat email), kebalikan arah pemuatan biasa.");
  g("signal", "signal (SIGTERM, SIGKILL)", "sinyal (SIGTERM, SIGKILL)", ["sigterm", "sigkill", "sigint", "signal", "signals"], "mod-1-1", 1, "A message the operating system sends to a program. SIGTERM asks it politely to stop; SIGKILL stops it at once and cannot be refused.", "Pesan yang dikirim sistem operasi ke sebuah program. SIGTERM memintanya berhenti dengan sopan; SIGKILL menghentikannya seketika dan tak bisa ditolak.");
  g("process-pid", "process and PID", "proses dan PID", ["pid", "process"], "mod-1-1", 1, "A process is one running copy of a program. Each has its own memory and an id number, the PID.", "Proses adalah satu salinan program yang berjalan. Masing-masing punya memori sendiri dan nomor id, yaitu PID.");
